import { z } from 'zod/v3';
import path from 'path';
import {
  registerIntentTool,
  requiredText,
  localChange,
  localRead,
  optionArgs,
  invalidIntent,
  type IntentToolDependencies,
} from './intentTool';
import { withDesignProfiles } from './profileAccess';
import { contextRequest } from '../cli/commands/contextRequest';
import { okResult } from '../cli/envelope';
import { getPluginName } from '../hosts/pluginContext';
import {
  GuidanceUploadSchema,
  GuidanceUploadUpdateSchema,
} from '../types/guidance';

export const registerPreferenceTools = (
  dependencies: IntentToolDependencies,
): void => {
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_save_design_preference',
      title: 'Save design preference',
      description:
        'Save a persistent design instruction or replace fields of the explicitly named contextId. Creating requires title and file or a nonempty references manifest. Omitted update fields are preserved; isEnabled controls future default use. Files are retained copies; repository URLs and directories stay pointers unless explicitly approved files are supplied. Does not save or execute verifier code.',
      shape: {
        contextId: requiredText.optional(),
        title: requiredText.optional(),
        file: requiredText.optional(),
        references: requiredText.optional(),
        isEnabled: z.boolean().optional(),
      },
      annotations: localChange,
    },
    async (input) => {
      if (
        !input.contextId &&
        (!input.title || (!input.file && !input.references))
      )
        return invalidIntent(
          'rivet_save_design_preference',
          'Creating requires title and file or references.',
        );
      if (
        input.contextId &&
        input.title === undefined &&
        input.file === undefined &&
        input.references === undefined &&
        input.isEnabled === undefined
      )
        return invalidIntent(
          'rivet_save_design_preference',
          'Provide at least one changed field.',
        );
      return withDesignProfiles(
        'rivet_save_design_preference',
        async (profiles) => {
          if (
            input.contextId &&
            !input.title &&
            !input.file &&
            !input.references
          )
            return profiles.updateGuidance({
              id: input.contextId,
              isEnabled: input.isEnabled,
            });
          const request = await contextRequest([
            input.contextId ? 'update' : 'add',
            ...(input.contextId ? [input.contextId] : []),
            ...optionArgs('--title', input.title),
            ...optionArgs('--file', input.file),
            ...optionArgs('--references', input.references),
          ]);
          if ('envelope' in request)
            throw new Error(
              request.envelope.ok
                ? 'Unexpected saved instruction result'
                : request.envelope.error.message,
            );
          const body = {
            ...(request.body as Record<string, unknown>),
            ...(input.isEnabled === undefined
              ? {}
              : { isEnabled: input.isEnabled }),
          };
          return input.contextId
            ? profiles.updateGuidance({
                id: input.contextId,
                ...GuidanceUploadUpdateSchema.parse(body),
              })
            : profiles.addGuidance(GuidanceUploadSchema.parse(body));
        },
      );
    },
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_remove_design_preference',
      title: 'Remove design preference',
      description:
        'Delete the explicitly named saved instruction and its associated verifier recipe/package from current preferences. Retained historical generation receipts are not rewritten. This is separate from disabling a preference or removing only its check.',
      shape: { contextId: requiredText },
      annotations: localChange,
    },
    async (input) =>
      withDesignProfiles('rivet_remove_design_preference', (profiles) =>
        profiles.removeGuidance(input.contextId),
      ),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_save_design_check',
      title: 'Save reusable design check',
      description:
        'Save or replace a checking recipe and optional authored Node verifier package for an existing instruction, bound to its inspected sourceDigest. Package source is retained locally. Saving never runs the code and does not create an automatic gate. Source edits and check saves are separate operations.',
      shape: {
        contextId: requiredText,
        sourceDigest: requiredText,
        recipeFile: requiredText,
        packageFile: requiredText.optional(),
      },
      annotations: localChange,
    },
    async (input) =>
      withDesignProfiles('rivet_save_design_check', async (profiles) => {
        const request = await contextRequest([
          'update',
          input.contextId,
          '--verifier',
          input.recipeFile,
          '--source-digest',
          input.sourceDigest,
          ...optionArgs('--verifier-package', input.packageFile),
        ]);
        if ('envelope' in request)
          throw new Error(
            request.envelope.ok
              ? 'Unexpected check result'
              : request.envelope.error.message,
          );
        return profiles.updateGuidance({
          id: input.contextId,
          ...GuidanceUploadUpdateSchema.parse(request.body),
        });
      }),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_remove_design_check',
      title: 'Remove saved design check',
      description:
        'Remove the saved checking recipe and executable package from the named instruction. Keeps the instruction and its future generation defaults. Does not execute the package or erase historical check reports.',
      shape: { contextId: requiredText },
      annotations: localChange,
    },
    async (input) =>
      withDesignProfiles('rivet_remove_design_check', (profiles) =>
        profiles.updateGuidance({ id: input.contextId, verifier: null }),
      ),
  );
  registerIntentTool(
    dependencies,
    {
      name: 'rivet_run_design_check',
      title: 'Prepare local design check',
      description:
        'Return executable arguments for the host to run the selected saved Node verifier. This tool does not execute code, read the input file, materialize a package, or write evidence. Invoke the returned executable, args and optional env through the host execution tool only for user-requested verification. Plugin env fields preserve installation identity and grant no permissions. The host controls sandboxing and approvals; Rivet adds no sandbox. The CLI validates the current saved package and input, filters inherited environment variables, supervises execution, and writes evidence and a report. Denied or unavailable approval must not be bypassed.',
      shape: {
        contextId: requiredText,
        project: requiredText,
        inputFile: requiredText,
        outputDirectory: requiredText.optional(),
      },
      annotations: localRead,
    },
    async (input) => {
      const projectPath = path.resolve(input.project);
      const pluginName = getPluginName();
      const inputFile = path.resolve(input.inputFile);
      const outputDirectory = input.outputDirectory
        ? path.resolve(input.outputDirectory)
        : path.join(projectPath, '.rivet', 'verifier-runs');
      return okResult('rivet_run_design_check', {
        execution: 'host_required',
        contextId: input.contextId,
        projectPath,
        inputFile,
        outputDirectory,
        nextAction: {
          action: 'run_design_check',
          executable: process.execPath,
          ...(pluginName
            ? { env: { RIVET_PLUGIN_NAME: pluginName, NODE_ENV: 'production' } }
            : {}),
          args: [
            path.resolve(__dirname, '../../bin/rivet.js'),
            'context',
            'verify',
            input.contextId,
            '--project',
            projectPath,
            '--input',
            inputFile,
            '--output-directory',
            outputDirectory,
          ],
          message:
            'Run this executable with these arguments and any supplied env fields through the current host execution tool. The env fields preserve the plugin installation identity; the host sandbox and approval policy still apply. If access is denied or approval is unavailable, report the blocked operation without retrying through the MCP server or broader privileges.',
        },
      });
    },
  );
};
